-- Món ăn Viện Dinh dưỡng đã cân (suất ăn thật ở Hà Nội, Hải Phòng, miền Bắc), để tra khi thêm món và xem ở Khám phá; số liệu là của 1 suất
CREATE TABLE mon_tra_cuu (
  id SERIAL PRIMARY KEY,
  -- Mã của món trên trang Viện Dinh dưỡng, ví dụ HAN-113090
  ma_so TEXT NOT NULL UNIQUE,
  ten_mon TEXT NOT NULL,
  -- Tên không dấu Viện ghi sẵn, để gõ "pho bo" cũng tìm ra "Phở bò"
  ten_khong_dau TEXT NOT NULL,
  -- Tên bỏ số lượng hoặc giá ở cuối, ví dụ "Bánh gối" của "Bánh gối 3 cái"; phần cắt ra ghi ở ghi_chu_suat (null là tên không có)
  ten_goc TEXT NOT NULL,
  ghi_chu_suat TEXT,
  so_calo NUMERIC(6, 1) NOT NULL CHECK (so_calo >= 0),
  dam_g NUMERIC(6, 1) NOT NULL CHECK (dam_g >= 0),
  tinh_bot_g NUMERIC(6, 1) NOT NULL CHECK (tinh_bot_g >= 0),
  beo_g NUMERIC(6, 1) NOT NULL CHECK (beo_g >= 0),
  -- Muối là số "tương đương muối" Viện ghi sẵn từ natri
  muoi_g NUMERIC(6, 1) NOT NULL CHECK (muoi_g >= 0),
  -- Ảnh suất ăn của Viện, có bảng nguyên liệu và số gam
  anh_url TEXT NOT NULL,
  -- Nhóm để lọc ở Khám phá, xếp theo chữ đầu tên món vì nhóm của Viện lẫn lộn; xét lần lượt bun_pho, com_chao_xoi, che_do_uong, banh, không khớp thì mon_khac
  nhom_mon TEXT NOT NULL DEFAULT 'mon_khac' CHECK (nhom_mon IN ('bun_pho', 'com_chao_xoi', 'che_do_uong', 'banh', 'mon_khac')),
  -- Khám phá chỉ hiện 1 bản cho mỗi món (King chốt 23/10/2026); kính lúp ở màn thêm món thấy đủ
  hien_o_kham_pha BOOLEAN NOT NULL DEFAULT true,
  -- Món uống bằng ly: thực đơn không chọn cho bữa phụ (King chốt 11/11/2026); vẫn hiện ở Khám phá và Tìm món
  la_do_uong BOOLEAN NOT NULL DEFAULT false,
  nguon TEXT NOT NULL,
  lien_ket TEXT NOT NULL,
  ngay_hieu_luc DATE NOT NULL
);

-- Chép 414 món từ trang Viện ngày 09/10/2026 (đủ calo, đạm, tinh bột, béo, muối; bỏ HAP-211021, HAP-211063 vì calo lệch hơn 20% so với đạm x 4 + tinh bột x 4 + béo x 9); đã xóa 6 món mang tên quán và 6 bản mã SFF trùng khít, đã sửa tên chép sai, không đổi số nào (NguonSoLieu.md)

-- Bún, phở, miến: tên bắt đầu bằng "bún", "phở", "miến", "mỳ", "mì", "hủ tiếu", "bánh canh", "bánh đa", "hoành thánh" (94 món)

-- Cơm, cháo, xôi: tên bắt đầu bằng "cơm", "cháo", "xôi" (45 món)

-- Chè, đồ uống: tên bắt đầu bằng "chè", "kem", "sữa chua", "nước", "cà phê", "caramen", "tào phớ", "hoa quả", "sinh tố", "trà", "sữa tươi", "thạch", "quả", "nha đam", "sủi dìn"; la_do_uong = true với món uống bằng ly (tên bắt đầu bằng "nước", "cà phê", "sữa tươi"; sữa chua không tính, King chốt 11/11/2026) (58 món)

-- Bánh: tên bắt đầu bằng "bánh" (71 món)

-- Món khác: tên không khớp nhóm nào ở trên (82 món)

-- Ẩn ở Khám phá, kính lúp vẫn thấy: cùng tên gốc với một món đang hiện nhưng khẩu phần khác (24 món)

-- Ẩn ở Khám phá: suất gồm nhiều món (tên bắt đầu bằng "cơm suất", "cơm bình dân", "cơm bụi", "set"), Khám phá là nơi xem từng món (26 món)

-- Ẩn ở Khám phá: sửa tên chép sai xong thì trùng tên một món đang hiện (2 món)
